mapper.update:
UPDATE locker_zone
SET name = #{name}, rows_count = #{rowsCount}, cols_count = #{colsCount}, total_count = #{totalCount}
WHERE id = #{id}

mapper.select:
SELECT COUNT(*) FROM locker l
WHERE l.zone_id = #{zoneId}
  AND EXISTS (
      SELECT 1 FROM membership m
      WHERE m.locker_id = l.id AND m.type = 'LOCKER' AND m.status IS NULL
  )
